  3	public final class BuildHeap {
  4	
  5	    private BuildHeap() {
  6	        // Utility class.
  7	    }
  8	
  9	    public static void buildHeap(int[] values) {
 10	        new HeapView(values).buildMaxHeap();
 11	    }
 12	
 13	    public static int[] buildHeapCopy(int[] values) {
 14	        int[] heap = Arrays.copyOf(validateNotNull(values), values.length);
 15	        buildHeap(heap);
 16	        return heap;
 17	    }
