 31	    private static final class HeapView {
 32	
 33	        private final int[] values;
 34	        private final int size;
 35	
 36	        private HeapView(int[] values) {
 37	            this.values = validateNotNull(values);
 38	            this.size = values.length;
 39	        }
 40	
 41	        private void buildMaxHeap() {
 42	            if (size < 2) {
 43	                return;
 44	            }
 45	
 46	            for (int parentIndex = lastParentIndex(); parentIndex >= 0; parentIndex--) {
 47	                siftDown(parentIndex);
 48	            }
 49	        }
 50	
 51	        private boolean isMaxHeap() {
 52	            for (int parentIndex = 0; parentIndex <= lastParentIndex(); parentIndex++) {
 53	                if (hasGreaterChild(parentIndex, leftChildIndex(parentIndex))) {
 54	                    return false;
 55	                }
 56	
 57	                if (hasGreaterChild(parentIndex, rightChildIndex(parentIndex))) {
 58	                    return false;
 59	                }
 60	            }
 61	
 62	            return true;
 63	        }
 64	
 65	        private void siftDown(int parentIndex) {
 66	            int currentIndex = parentIndex;
 67	
 68	            while (true) {
 69	                int largestIndex = currentIndex;
 70	                largestIndex = largerIndex(largestIndex, leftChildIndex(currentIndex));
 71	                largestIndex = largerIndex(largestIndex, rightChildIndex(currentIndex));
 72	
 73	                if (largestIndex == currentIndex) {
 74	                    return;
 75	                }
 76	
 77	                swap(currentIndex, largestIndex);
 78	                currentIndex = largestIndex;
 79	            }
 80	        }
 81	
 82	        private boolean hasGreaterChild(int parentIndex, int childIndex) {
 83	            return childIndex < size && values[parentIndex] < values[childIndex];
 84	        }
 85	
 86	        private int largerIndex(int currentLargestIndex, int candidateIndex) {
 87	            if (candidateIndex < size && values[candidateIndex] > values[currentLargestIndex]) {
 88	                return candidateIndex;
 89	            }
 90	
 91	            return currentLargestIndex;
 92	        }
 93	
 94	        private int lastParentIndex() {
 95	            return (size / 2) - 1;
 96	        }
 97	
 98	        private int leftChildIndex(int parentIndex) {
 99	            return (2 * parentIndex) + 1;
100	        }
101	
102	        private int rightChildIndex(int parentIndex) {
103	            return (2 * parentIndex) + 2;
104	        }
105	
106	        private void swap(int firstIndex, int secondIndex) {
107	            int temp = values[firstIndex];
108	            values[firstIndex] = values[secondIndex];
109	            values[secondIndex] = temp;
110	        }
111	    }
